# Persistent entities (table-backed structs)
# Count distinct Go packages outside store/ that reference store.<Type>

perl -e '
use strict;
use warnings;

my @entities = qw(
  Attachment IdentityProvider Inbox InstanceSetting Memo MemoRelation
  MemoShare Reaction User UserIdentity UserSetting
);

# Also related but maybe not "entities"
my @extra = qw(
  AuthenticationConfigState AuthenticationConfigMutation DeleteUserResult
  RefreshTokenQueryResult PATQueryResult
);

my @all = (@entities, @extra);

open my $cmd, "-|", q{find /bench/repo -name "*.go" ! -path "*/.git/*" ! -path "*/proto/*" ! -path "*/web/*"} or die;
my @files;
while (<$cmd>) { chomp; push @files, $_; }

# package path = directory relative to repo, excluding store and store/*
sub pkg_of {
  my ($path) = @_;
  $path =~ s{^/bench/repo/}{};
  $path =~ s{/[^/]+\.go$}{};
  return $path;
}

sub is_data_layer {
  my ($pkg) = @_;
  return 1 if $pkg eq "store";
  return 1 if $pkg =~ m{^store/};
  return 0;
}

my %hits; # type -> { pkg => count }
my %examples;

for my $file (@files) {
  my $pkg = pkg_of($file);
  next if is_data_layer($pkg);
  open my $fh, "<", $file or next;
  my $content = do { local $/; <$fh> };
  for my $t (@all) {
    # store.Type or *store.Type
    my $n = () = $content =~ /(?:\*| )store\.\Q$t\E\b/g;
    # also store.Type in other contexts
    if ($n == 0) {
      $n = () = $content =~ /store\.\Q$t\E\b/g;
    }
    if ($content =~ /store\.\Q$t\E\b/) {
      $hits{$t}{$pkg}++;
      $examples{$t}{$pkg} = $file unless $examples{$t}{$pkg};
    }
  }
}

print "Entity package fan-out (outside store/):\n";
my @ranked = sort { scalar(keys %{$hits{$b}}) <=> scalar(keys %{$hits{$a}}) || $a cmp $b } @all;
for my $t (@ranked) {
  my $n = scalar keys %{$hits{$t}||{}};
  print sprintf("%2d  %s\n", $n, $t);
  for my $p (sort keys %{$hits{$t}||{}}) {
    print "      $p\n";
  }
}
'

